// ZENORIA_M3A_V1 : logo des PDF (facture et export RGPD), genere depuis public/images/logo-facture.png.
// Fichier GENERE : si le logo change, regenerer ce module (meme image encodee en base64).
// Pas de lecture disque : fonctionne sur Vercel comme sur Cloudflare Workers.
export const INVOICE_LOGO_BASE64 =
  "";

export function getInvoiceLogoBytes() {
  const bin = atob(INVOICE_LOGO_BASE64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
